import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import PageStructure from 'flarum/forum/components/PageStructure';
import DialogList from './DialogList';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Stream from 'flarum/common/utils/Stream';
import InfoTile from 'flarum/common/components/InfoTile';
import MessagesSidebar from './MessagesSidebar';
import MessagesPageHero from './MessagesPageHero';
import DialogSection from './DialogSection';
import listItems from 'flarum/common/helpers/listItems';
import ItemList from 'flarum/common/utils/ItemList';
import Dropdown from 'flarum/common/components/Dropdown';
import Button from 'flarum/common/components/Button';
import classList from 'flarum/common/utils/classList';
export default class MessagesPage extends Page {
  selectedDialog = (() => Stream(null))();
  currentDialogId = null;
  loadingDialog = false;
  oninit(vnode) {
    super.oninit(vnode);
    if (!app.session.user) {
      m.route.set(app.route('index'));
      return;
    }
    app.current.set('noTagsList', true);
    if (app.dialogs.hasItems()) {
      this.initDialog();
    } else {
      // The list failing is no reason not to open a conversation the address names.
      app.dialogs.refresh().catch(() => {}).then(() => this.initDialog());
    }
  }
  dialogRequestParams() {
    return {
      include: 'users.groups'
    };
  }
  async initDialog() {
    const dialogId = m.route.param('id');
    this.currentDialogId = dialogId;
    const title = app.translator.trans('flarum-messages.forum.messages_page.title', {}, true);
    let dialog = null;
    if (dialogId) {
      dialog = app.store.getById('dialogs', dialogId) || null;

      // Not seen yet, or seen only through a message, without its participants.
      if (!dialog?.users()) {
        this.loadingDialog = true;
        m.redraw();
        try {
          dialog = await app.store.find('dialogs', dialogId, this.dialogRequestParams());
        } catch {
          // Gone, or not theirs; the request's own alert says which. Back to the list.
          this.loadingDialog = false;
          m.route.set(app.route('messages'));
          return;
        }
        this.loadingDialog = false;
      }
    } else if (app.screen() !== 'phone') {
      // A phone shows the list on its own. Opening the first conversation
      // behind it would mark it read without it ever being seen.
      dialog = app.dialogs.getAllItems()[0] || null;
    }
    this.selectedDialog(dialog);
    if (dialog) {
      app.setTitle(dialog.title());
      app.history.push('dialog', dialog.title());
    } else {
      app.setTitle(title);
      app.history.push('messages', title);
    }
    m.redraw();
  }
  onupdate(vnode) {
    super.onupdate(vnode);

    // Scroll the dialog list to the active dialog item if present and not visible.
    const dialogElement = this.element.querySelector('.DialogListItem.active');
    const container = this.element.querySelector('.DialogList');
    if (dialogElement && container && $(container).offset().top + container.clientHeight <= $(dialogElement).offset().top) {
      dialogElement.scrollIntoView();
    }
  }
  view() {
    return m(PageStructure, {
      className: "MessagesPage Page--vertical",
      loading: false,
      hero: this.hero.bind(this),
      sidebar: () => m(MessagesSidebar, null)
    }, app.dialogs.isInitialLoading() ? m(LoadingIndicator, null) : !app.dialogs.hasItems() && !this.selectedDialog() && !this.loadingDialog ? m(InfoTile, {
      icon: "far fa-envelope-open"
    }, app.translator.trans('flarum-messages.forum.messages_page.empty_text')) : m("div", {
      className: classList('MessagesPage-content', {
        'MessagesPage-content--onDialog': this.currentDialogId
      })
    }, this.contentItems().toArray()));
  }
  hero() {
    return m(MessagesPageHero, null);
  }
  contentItems() {
    const items = new ItemList();
    items.add('sidebar', m("div", {
      className: "MessagesPage-sidebar",
      key: "sidebar"
    }, m("div", {
      className: "IndexPage-toolbar",
      key: "toolbar"
    }, m("ul", {
      className: "IndexPage-toolbar-view"
    }, listItems(this.viewItems().toArray())), m("ul", {
      className: "IndexPage-toolbar-action"
    }, listItems(this.actionItems().toArray()))), m(DialogList, {
      key: "list",
      state: app.dialogs,
      activeDialog: this.selectedDialog()
    })), 100);
    const dialog = this.selectedDialog();

    // Added only when there is something to show: a hole beside the keyed list
    // makes Mithril throw, and every redraw of the page with it.
    if (dialog) {
      items.add('dialog', m(DialogSection, {
        key: "dialog",
        dialog: dialog,
        onback: () => {
          // A route change, so the browser's own back button agrees with ours.
          m.route.set(app.route('messages'));
        }
      }), 80);
    } else if (this.loadingDialog) {
      items.add('dialog', m(LoadingIndicator, {
        key: "loading",
        display: "block"
      }), 80);
    }
    return items;
  }

  /**
   * Build an item list for the part of the toolbar which is concerned with how
   * the results are displayed. By default this is just a select box to change
   * the way discussions are sorted.
   */
  viewItems() {
    const items = new ItemList();
    const sortMap = app.dialogs.sortMap();
    const sortOptions = Object.keys(sortMap).reduce((acc, sortId) => {
      const sort = sortMap[sortId];
      acc[sortId] = typeof sort !== 'string' ? sort.label : app.translator.trans(`flarum-messages.forum.index_sort.${sortId}_button`);
      return acc;
    }, {});
    items.add('sort', m(Dropdown, {
      buttonClassName: "Button",
      label: sortOptions[app.dialogs.getParams()?.sort || 0] || Object.values(sortOptions)[0],
      accessibleToggleLabel: app.translator.trans('core.forum.index_sort.toggle_dropdown_accessible_label')
    }, Object.keys(sortOptions).map(value => {
      const label = sortOptions[value];
      const active = (app.dialogs.getParams().sort || Object.keys(sortMap)[0]) === value;
      return m(Button, {
        icon: active ? 'fas fa-check' : true,
        onclick: () => app.dialogs.changeSort(value),
        active: active
      }, label);
    })));
    return items;
  }

  /**
   * Build an item list for the part of the toolbar which is about taking action
   * on the results. By default, this is just a "mark all as read" button.
   */
  actionItems() {
    const items = new ItemList();
    items.add('refresh', m(Button, {
      title: app.translator.trans('flarum-messages.forum.messages_page.refresh_tooltip'),
      "aria-label": app.translator.trans('flarum-messages.forum.messages_page.refresh_tooltip'),
      icon: "fas fa-sync",
      className: "Button Button--icon",
      onclick: () => {
        app.dialogs.refresh();
      }
    }));
    if (app.session.user) {
      items.add('markAllAsRead', m(Button, {
        title: app.translator.trans('flarum-messages.forum.messages_page.mark_all_as_read_tooltip'),
        "aria-label": app.translator.trans('flarum-messages.forum.messages_page.mark_all_as_read_tooltip'),
        icon: "fas fa-check",
        className: "Button Button--icon",
        onclick: () => app.dialogs.markAllAsRead()
      }));
    }
    return items;
  }
}
flarum.reg.add('flarum-messages', 'forum/components/MessagesPage', MessagesPage);